import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"55、【豐】 離下震上","description":"周易尚氏學 - 55、【豐】 離下震上","frontmatter":{"title":"55、【豐】 離下震上","description":"周易尚氏學 - 55、【豐】 離下震上"},"headers":[],"relativePath":"classics/shangshi/060.md","filePath":"classics/shangshi/060.md"}'),s={name:"classics/shangshi/060.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_55、【豐】-離下震上" tabindex="-1">55、【豐】 離下震上 <a class="header-anchor" href="#_55、【豐】-離下震上" aria-label="Permalink to “55、【豐】 離下震上”">​</a></h1><p>雷電皆至東。故豐。說文。豐豆之豐滿者也。四陽遇重陰。故亨。震為王。假至也。王假之。言四宜上升至五也。震為樂。故曰勿憂。離為日。中謂五。宜日中者。謂四升五。當位如日中也。</p><p>彖曰。豐。大也。明以動故豐。王假之。尚大也。勿憂宜日中。宜照天下也。日中則昃。月盈則食。天地盈虛。與時消息。而況於人乎。況於鬼神乎。</p><p>尚上也。大謂陽。尚大謂四宜上升五。四升五則日中。光照天下。兌月離日。日中則昃。月盈則食。言豐之不足恃也。</p><p>象曰。雷電皆至。豐。君子以折獄致刑。</p><p>先天離東。後天震東。故曰皆至。離明故可折獄。震威故宜致刑。</p><p>初九。遇其配主。雖旬無咎。往有尚。</p><p>陰陽相配。配主謂二。二五為卦主。故五曰夷主。配鄭作妃。義同也。離為日。日之數十。十日為旬。初居日之末。故曰旬。至旬則癸日也。後漢鄧禹傳。明日癸亥。匡等以六甲窮日。不出。是至旬當有咎。自古相傳如是也。雖旬無咎者。以初遇陰也。二陰。故往有尚。</p><h3 id="象曰。雖旬無咎。過旬災也。" tabindex="-1">象曰。雖旬無咎。過旬災也。 <a class="header-anchor" href="#象曰。雖旬無咎。過旬災也。" aria-label="Permalink to “象曰。雖旬無咎。過旬災也。”">​</a></h3><p>旬者盈數。過旬災。仍月盈則食之意也。</p><p>六二。豐其部。日中見鬥。往得疑疾。有孚發若。吉。</p><p>二至五五大坎。坎為隱伏。故中四爻象皆閻昧。部（上草）。虞翻雲。日蔽雲中稱部（上草）。虞未申其義。然坎雲在離日之上。正日蔽雲中也。離為星。故日鬥。又震亦為鬥。鬥七星也。言離日有障蔽。日隱而星見也。二巽體。巽為疑為疾。巽初六象曰。進退志疑是也。五不應。故往得疑疾。然二承重陽。手於三四。發若者。言其順利也。陰孚陽故吉。離星巽疑象詳焦氏易詁。</p><h3 id="象曰。有孕發若。信以發志也。" tabindex="-1">象曰。有孕發若。信以發志也。 <a class="header-anchor" href="#象曰。有孕發若。信以發志也。" aria-label="Permalink to “象曰。有孕發若。信以發志也。”">​</a></h3><p>有孚故信。巽為志。信以發志者。言陰孚於陽。得行其志也。</p><p>九三。豐其沛。日中見沫。折其右肱。無咎。</p><p>沛大雨貌。孟子沛然下雨。易林泰之豐雲。龍蛇所聚。大水來處。滂滂沛沛。使我無賴。九家雲。大暗謂之沛。沫。子夏傳星之小者。日中見沫者。言當日中而昏暗見小星也。三兌體。兌為雨。故曰沛。兌為晦。故曰見沫。艮為肱三應在上。上艮覆。故折其右肱。兌為右為折也。然三當位有應。故無咎。</p><h3 id="象曰。豐其沛。不可大事也。折其右肱。終不可用也。" tabindex="-1">象曰。豐其沛。不可大事也。折其右肱。終不可用也。 <a class="header-anchor" href="#象曰。豐其沛。不可大事也。折其右肱。終不可用也。" aria-label="Permalink to “象曰。豐其沛。不可大事也。折其右肱。終不可用也。”">​</a></h3><p>三遇敵。不利往。所應為陰。陰小故不可大事。三雖有應而折肱。故終不可用。虞氏以二至五大過死解。似非。</p><p>九四。豐其蔀，日中見鬥。遇其夷主，吉。</p><p>易林升之臨雲。據鬥運樞。以震為鬥。茲震在日上。以為障蔽。故仍曰豐其部（上草）。日中見鬥。主謂五。五柔爻。故曰夷主。詩周頌有夷之行。毛傳。夷易也。陽遇陰則通。故曰易曰。曰吉。</p><h3 id="象曰。豐其蔀-位未當也。日中見鬥-幽不明也。遇其夷主-吉行也。" tabindex="-1">象曰。豐其蔀，位未當也。日中見鬥，幽不明也。遇其夷主，吉行也。 <a class="header-anchor" href="#象曰。豐其蔀-位未當也。日中見鬥-幽不明也。遇其夷主-吉行也。" aria-label="Permalink to “象曰。豐其蔀，位未當也。日中見鬥，幽不明也。遇其夷主，吉行也。”">​</a></h3><p>易林升之臨雲。據鬥運樞，以震為鬥。茲震在日上。以為障蔽。故仍日半其部（上草）日中見鬥。主謂五。五柔爻。故曰夷主。詩周頌有夷之行。創傳。夷易也。陽遇陰則通。故曰易。日吉。象曰。半其部（上草）。位不當也。日中見鬥。幽不明也。遇其夷主。吉行也。兌為昧。故幽不明。陽遇陰故志行。郭京舉正行上脫志字。宜從。</p><p>六五。來章。有慶譽。吉。</p><p>呼九四來五。當位居中。彖所謂日中也。故曰章。五得位。故有慶譽吉。或謂四往五不能曰來。豈知六五呼四。當然曰來。況睽上九雲。往遇雨則吉。是上來內。易有時亦言往也。需上曰有不速之客三人來。是三往上亦曰來也。蹇五大蹇朋來。是陽往五亦曰來也。上曰來章。又何疑乎。</p><h3 id="象曰。六五之吉。有慶也。" tabindex="-1">象曰。六五之吉。有慶也。 <a class="header-anchor" href="#象曰。六五之吉。有慶也。" aria-label="Permalink to “象曰。六五之吉。有慶也。”">​</a></h3><p>慶謂陽升五得位。</p><p>上六。豐其屋，蔀其家，窺其戶，闃其無人，三歲不覿，兇。</p><p>屋家戶。後儒不知其象。穿鑿百出。愈說愈晦。此覆象失傳之故也。按虞注云。從外窺三。又九家說重門系柝雲。豫不艮。從外示之。上震復為艮。豐上六從外示內。亦艮也。艮為屋為家為戶。中爻大坎。故障蔽其家。艮為觀。下視。故曰窺其戶。震為人。上應在三。三巽伏。故闃寂無人。闃虞雲空也。鄭雲無人兒。震為歲。數三。故曰三歲不覿而兇也。闃孟喜作室。窒古與空通用。列子黃帝篇。玉人潛行不空。莊子達生篇引作室。然則孟虞之詁同也。</p><h3 id="象曰。豐其屋。天際祥也。窺其戶闃其無人。自藏也。" tabindex="-1">象曰。豐其屋。天際祥也。窺其戶闃其無人。自藏也。 <a class="header-anchor" href="#象曰。豐其屋。天際祥也。窺其戶闃其無人。自藏也。" aria-label="Permalink to “象曰。豐其屋。天際祥也。窺其戶闃其無人。自藏也。”">​</a></h3><p>五天位。上在五外。故曰天際。說文祥福也善也。徐肱曰。凡吉凶之先見其兆者。皆曰祥。故孟喜曰。天際祥。天降下惡祥也。自藏謂三。三宜應上。而巽為伏。故曰自藏。釋無人之故也。祥從鄭本。正義作翔。翔樣音同通用。此卦舊解。因易理失傳。不知二五為卦主。於是遇其配主。遇其夷主。皆以震為主。權櫟不合。因卦象失傳。於是爻變卦變。雜然並用。以求其象。學者只涵泳白文。或尚能明其一二。若即舊解求之。則愈茫昧疑惑。真可慨也。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
